<?php
require_once __DIR__.'/../config/database.php';
require_once __DIR__.'/../includes/security.php';
require_once __DIR__.'/../includes/functions.php';
require_once __DIR__.'/../includes/portal.php';
$q=$pdo->prepare('SELECT s.id,s.status,p.name,p.min_grade FROM scholars s JOIN scholarship_programs p ON p.id=s.program_id WHERE s.user_id=?');$q->execute([$portalUser['id']]);$s=$q->fetch();$g=null;$docs=0;$due=0;
if($s){$q=$pdo->prepare('SELECT average,term FROM grade_records WHERE scholar_id=? ORDER BY created_at DESC,id DESC LIMIT 1');$q->execute([$s['id']]);$g=$q->fetch();$q=$pdo->prepare("SELECT COUNT(*) FROM document_requirements r LEFT JOIN scholar_documents d ON d.requirement_id=r.id AND d.scholar_id=? AND d.status='Approved' WHERE r.program_id=(SELECT program_id FROM scholars WHERE id=?) AND d.id IS NULL");$q->execute([$s['id'],$s['id']]);$docs=(int)$q->fetchColumn();$q=$pdo->prepare('SELECT COUNT(*) FROM document_requirements WHERE program_id=(SELECT program_id FROM scholars WHERE id=?) AND due_date>=CURDATE()');$q->execute([$s['id']]);$due=(int)$q->fetchColumn();}
portalStart('Dashboard','dashboard.php');echo '<div class="portal-grid"><article class="portal-stat"><span>Scholarship status</span><strong>'.h($s['status']??'Not assigned').'</strong><small>'.h($s['name']??'Contact the scholarship office').'</small></article><article class="portal-stat"><span>Current GWA</span><strong>'.h($g['average']??'—').'</strong><small>'.h($g['term']??'No grade recorded').'</small></article><article class="portal-stat"><span>Missing documents</span><strong>'.$docs.'</strong></article><article class="portal-stat"><span>Upcoming deadlines</span><strong>'.$due.'</strong></article></div><div class="portal-panel"><h2>Welcome, '.h($portalUser['full_name']).'</h2><p>Your dashboard displays live information from your scholarship records.</p><a class="portal-button" href="scholarship.php">View scholarship</a></div>';portalEnd();